import{f as i,D as t,o as s,c as o,k as n,a as r,G as d,ar as h}from"./chunks/framework.HWAOx3Ef.js";const p=JSON.parse('{"title":"Farbschema der Eingabehistorie","description":"","frontmatter":{},"headers":[],"relativePath":"technik/adr/ui/adr011-dse-farbschema-eingabehistorie.md","filePath":"technik/adr/ui/adr011-dse-farbschema-eingabehistorie.md"}'),l={name:"technik/adr/ui/adr011-dse-farbschema-eingabehistorie.md"};function u(c,e,b,m,g,k){const a=t("adr-status");return s(),o("div",null,[e[0]||(e[0]=n("h1",{id:"farbschema-der-eingabehistorie",tabindex:"-1"},[r("Farbschema der Eingabehistorie "),n("a",{class:"header-anchor",href:"#farbschema-der-eingabehistorie","aria-label":'Permalink to "Farbschema der Eingabehistorie"'},"​")],-1)),e[1]||(e[1]=n("h2",{id:"status",tabindex:"-1"},[r("Status "),n("a",{class:"header-anchor",href:"#status","aria-label":'Permalink to "Status"'},"​")],-1)),d(a,{status:"accepted"}),e[2]||(e[2]=h('<h2 id="kontext" tabindex="-1">Kontext <a class="header-anchor" href="#kontext" aria-label="Permalink to &quot;Kontext&quot;">​</a></h2><p>Um in der Eingabehistorie die Unterscheidung der verschiedenen Aktionen mit passenden Icons zu unterstützen, werden die Icons farbig dargestellt. Dabei ist es wichtig, auch barrierefreie Zugänglichkeit zu gewährleisten, sodass Nutzer mit visuellen Einschränkungen die Aktionen eindeutig erkennen können.</p><h2 id="entscheidung" tabindex="-1">Entscheidung <a class="header-anchor" href="#entscheidung" aria-label="Permalink to &quot;Entscheidung&quot;">​</a></h2><p>Die Erfassung aller Werte, die vom Wähler bestimmt werden, ist mit grünen Icons markiert. Darunter fallen das Hinzufügen von Stimmen sowie die Streichung von Kandidaten. Alle Aktionen zur Korrektur von vorherigen Eingaben werden mit roten Icons dargestellt.</p><p>Zusätzlich zur Farbgebung sollen die Icons durch unterschiedliche Formen oder Symbole erkennbar machen, ob eine Aktion eine Ergänzung oder eine Entfernung darstellt. Beispielsweise könnte ein Plus-Symbol für Ergänzungen (Hinzufügen) und ein Minus-Symbol für Entfernen verwendet werden. Diese visuellen Merkmale verbessern die Zugänglichkeit für Nutzer, die Farben nicht unterscheiden können.</p><h2 id="konsequenzen" tabindex="-1">Konsequenzen <a class="header-anchor" href="#konsequenzen" aria-label="Permalink to &quot;Konsequenzen&quot;">​</a></h2><p>Es ist schneller ersichtlich, ob es sich bei den letzten Eingaben um vom Wähler gesetzte Werte oder die Korrektur vorheriger Eingaben handelt. Die Kombination aus Farbgebung und Formmerkmalen stellt sicher, dass die Icons auch für Nutzer mit Farbsehschwächen oder anderen visuellen Einschränkungen verständlich sind.</p>',7))])}const E=i(l,[["render",u]]);export{p as __pageData,E as default};
